<template><view class="page" v-if="authorized"><view class="hero"><text class="title">会员商品销售政策</text><text class="subtitle">{{ deptName }} · 每个核算周期、每个商品独立维护</text></view><view class="actions"><button v-if="can('add')" class="primary" @tap="add">＋ 新增销售政策</button><button @tap="load">刷新</button></view><view class="card" v-for="row in rows" :key="row.policyId"><view class="row-head"><text class="name">{{ row.policyName }}</text><text class="status">{{ row.status === '1' ? '启用' : '停用' }}</text></view><text class="meta">{{ row.policyNo }} · {{ row.productName || row.productId || '商品' }}</text><view class="packages"><text v-for="p in row.packages || []" :key="p.packageId">{{ p.packageName || '套餐' }}：买{{ quantity(p.purchaseQuantity) }}送{{ quantity(p.giftQuantity) }} · ¥{{ money(p.packagePrice) }}</text><text v-if="!(row.packages || []).length" class="empty-inline">暂无套餐档位</text></view><view class="row-actions"><button @tap="view(row)">查看</button><button v-if="can('edit')" @tap="edit(row)">编辑</button><button v-if="can('sync')" @tap="sync(row)">同步到其他机构</button></view></view><view class="empty" v-if="!rows.length">暂无销售政策</view></view></template>
<script>
import { request } from '@/api/index.js'; import { hasActionPermission, requireModulePermission } from '@/utils/permission.js'; import { workContext } from '@/utils/workContext.js'
export default { data(){return{authorized:false,rows:[],deptName:'',deptId:''}}, onLoad(){this.authorized=requireModulePermission('campaignPolicy');const s=workContext.snapshot();this.deptId=s.currentDeptId;this.deptName=s.currentDept?.name||s.currentDept?.deptName||'未选择机构';if(this.authorized)this.load()}, methods:{can(a){return hasActionPermission('campaignPolicy',a)},quantity(v){return Number(v||0).toFixed(3).replace(/\.0+$/,'').replace(/(\.\d*?)0+$/,'$1')},money(v){return Number(v||0).toFixed(2)},async load(){const r=await request({url:'/member/campaign/policy/list',method:'GET',data:{pageNum:1,pageSize:200,deptId:this.deptId}});this.rows=r.rows||r.data||[]},add(){uni.navigateTo({url:'/pages/campaign-policy/form'})},view(r){uni.navigateTo({url:`/pages/campaign-policy/form?id=${r.policyId}&mode=view`})},edit(r){uni.navigateTo({url:`/pages/campaign-policy/form?id=${r.policyId}`})},sync(r){uni.navigateTo({url:`/pages/config-sync/index?type=CAMPAIGN_POLICY&sourceRecordId=${r.policyId}`})}}}
</script>
<style scoped>.page{min-height:100vh;background:#f4f7fb;padding:24rpx}.hero{padding:30rpx;background:linear-gradient(135deg,#0b74de,#1456b8);border-radius:22rpx;color:#fff}.title{display:block;font-size:38rpx;font-weight:700}.subtitle{display:block;margin-top:10rpx;font-size:23rpx;opacity:.85}.actions,.row-actions{display:flex;gap:14rpx;margin:20rpx 0}.actions button,.row-actions button{border:0;border-radius:12rpx;background:#eef3f8;color:#334155;padding:10rpx 20rpx}.primary{background:#0b74de!important;color:#fff!important}.card{background:#fff;border-radius:18rpx;padding:24rpx;margin-bottom:16rpx;box-shadow:0 8rpx 24rpx rgba(15,23,42,.06)}.row-head{display:flex;justify-content:space-between}.name{font-size:30rpx;font-weight:700}.status{color:#16865a}.meta,.packages{display:block;margin-top:12rpx;color:#64748b;font-size:23rpx}.packages text{display:block;padding:8rpx 0}.empty-inline{color:#94a3b8}.row-actions{justify-content:flex-end;margin-bottom:0}.empty{text-align:center;color:#94a3b8;padding:80rpx}</style>
